<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowDownLeft, ArrowUpRight, Banknote, CalendarDays, Check, ChevronRight, CircleAlert, ClipboardCheck, FileCheck2, FileText, FolderOpen, Landmark, LoaderCircle, ReceiptText, ScanLine, Search, ShieldCheck, X } from 'lucide-vue-next'
import { usePlatformStore } from '../stores/platform'

const store = usePlatformStore()
const route = useRoute()
const activeTab = ref('合同台账')
const incomingId = String(route.query.id || 'SZ-HT-2026-018')
const incomingFinding = store.findings.find(f => f.id === incomingId)
const selectedId = ref(incomingFinding?.sourceId || incomingId)
const keyword = ref('')
const selectedContract = computed(() => store.contracts.find(c => c.id === selectedId.value) || store.contracts[0])
const contracts = computed(() => store.contracts.filter(c => `${c.asset}${c.area}${c.id}`.includes(keyword.value)))
const ruralFindings = computed(() => store.findings.filter(f => f.domain === '农村三资'))
const contractFindings = computed(() => ruralFindings.value.filter(f => f.sourceId === selectedContract.value?.id))
const payments = computed(() => store.payments.filter(p => p.contractId === selectedContract.value?.id))
const isExpense = computed(() => selectedContract.value?.id === 'SZ-HT-2026-025')
const difference = computed(() => Math.max(0, (selectedContract.value?.receivable || 0) - (selectedContract.value?.received || 0)))
const drawerId = ref<string | null>(incomingFinding?.id || null)
const drawerFinding = computed(() => store.findings.find(f => f.id === drawerId.value))
const drawerContract = computed(() => store.contracts.find(c => c.id === drawerFinding.value?.sourceId))
const drawerPayments = computed(() => store.payments.filter(p => p.contractId === drawerContract.value?.id))
const verifying = ref(false)
const verifyStep = ref(-1)
const verifyRun = ref(0)
const verified = ref(false)
const assignmentOpen = ref(false)
const assignee = ref('第二监督检查室')
const deadline = ref('2026-11-12')
const actionMessage = ref('')
const addedReceipt = computed(() => payments.value.some(p => p.id.startsWith('PAY-MANUAL-')))
const taskForFinding = computed(() => store.tasks.find(t => t.source === '农村三资' && t.sourceId === drawerFinding.value?.id))
const steps = ['合同要素识别', '收款流水匹配', '规则交叉比对', '疑点辅助汇总']
const money = (n: number) => n.toLocaleString('zh-CN')

function chooseContract(id: string) {
  verifyRun.value++
  verifying.value = false
  selectedId.value = id
  verified.value = false
  verifyStep.value = -1
  actionMessage.value = ''
}
async function verify() {
  if (verifying.value) return
  verifying.value = true
  verified.value = false
  const run = ++verifyRun.value
  const contractId = selectedContract.value?.id
  for (let i = 0; i < steps.length; i++) {
    verifyStep.value = i
    await new Promise(resolve => setTimeout(resolve, 470))
    if (run !== verifyRun.value) return
  }
  verifyStep.value = 4
  verified.value = true
  verifying.value = false
  store.addEvent('三资智能核验', `${contractId}：完成合同、收款与规则模拟核验`)
}
function openFinding(id: string) {
  drawerId.value = id
  assignmentOpen.value = false
  actionMessage.value = ''
}
function createTask() {
  const finding = drawerFinding.value
  if (!finding) return
  store.addTask({ source: '农村三资', sourceId: finding.id, title: finding.title, area: finding.area, priority: finding.priority, assignee: assignee.value, deadline: deadline.value })
  finding.status = '处理中'
  store.addEvent('人工发起三资核查', `${finding.title} · ${assignee.value} · 截止 ${deadline.value}`)
  assignmentOpen.value = false
  actionMessage.value = '核查任务已进入监督待办，责任人与办理时限已记录。'
}
function addReceipt() {
  const contract = selectedContract.value
  if (!contract || addedReceipt.value) return
  store.payments.push({ id: `PAY-MANUAL-${contract.id}`, contractId: contract.id, date: '2026-11-02', amount: difference.value, voucher: '人工补录演示凭证 · 待核实' })
  const amount = difference.value
  contract.received += amount
  contract.status = '补录待核实'
  const finding = ruralFindings.value.find(f => f.sourceId === contract.id)
  if (finding?.evidence[0]) {
    finding.evidence[0] = {
      source: `${contract.id} · 合同与收款流水（含人工补录）`,
      excerpt: `合同应收${money(contract.receivable)}元，当前已关联到账${money(contract.received)}元，账面待核对差额${money(Math.max(0, contract.receivable - contract.received))}元。其中${money(amount)}元为本次补录演示记录，凭证尚待核实。`,
      rule: '账面差额已补齐，但人工补录凭证仍须核实其真实性及业务归属',
      question: '补录记录是否对应真实到账？付款主体、金额与合同是否一致？请人工核对原始凭证后作出结论。',
    }
  }
  store.addEvent('补充收款记录', `${contract.id} 补录 ${money(amount)} 元演示记录，须人工核实凭证`)
  actionMessage.value = '已补充演示收款记录，账面差额已更新；凭证仍需人工核实。'
}
watch(() => route.query.id, value => {
  if (!value) return
  const id = String(value)
  const finding = store.findings.find(f => f.id === id)
  chooseContract(finding?.sourceId || id)
  drawerId.value = finding?.id || null
  activeTab.value = '合同台账'
})
</script>

<template>
  <div class="assets-page">
    <div class="page-heading">
      <div><div class="eyebrow">农村集体资产 · 收支核对</div><h1>农村三资监督</h1><p class="muted">从一份合同出发，让资产、资金与业务依据清晰相连。</p></div>
      <div class="heading-side"><span class="demo-tag"><span></span> 演示数据</span><span class="coverage">已接入 {{ store.contracts.length }} 份样例合同</span></div>
    </div>

    <div class="assets-tabs"><button v-for="(tab, index) in ['合同台账', '资产管理', '收支核对', '风险清单']" :key="tab" :class="{ active: activeTab === tab }" @click="activeTab = tab"><component :is="[FileText, Landmark, ReceiptText, ShieldCheck][index]" :size="16"/>{{ tab }}<span v-if="tab === '风险清单'" class="tab-count">{{ ruralFindings.length }}</span></button></div>

    <template v-if="selectedContract && activeTab === '合同台账'">
      <div class="contract-workspace">
        <aside class="contract-list panel">
          <div class="list-heading"><h3>合同档案</h3><span>{{ store.contracts.length }} 份</span></div>
          <label class="contract-search"><Search :size="16"/><input v-model="keyword" placeholder="搜索资产、乡镇或合同"/></label>
          <button v-for="contract in contracts" :key="contract.id" class="contract-choice" :class="{ selected: selectedId === contract.id }" @click="chooseContract(contract.id)">
            <span class="choice-meta">{{ contract.area }}<ChevronRight :size="15"/></span><strong>{{ contract.asset }}</strong><small>{{ contract.id }}</small><span class="choice-bottom"><span :class="['status-dot', contract.receivable > contract.received ? 'amber' : 'green']"></span>{{ contract.receivable > contract.received ? '收款记录待核对' : contract.id === 'SZ-HT-2026-025' ? '已关联付款' : '已关联收款' }}<b>¥ {{ money(contract.receivable) }}</b></span>
          </button>
          <div v-if="!contracts.length" class="empty">未找到匹配合同</div>
          <div class="source-foot"><FolderOpen :size="15"/> 村级合同样例库 · 本地模拟</div>
        </aside>

        <section class="contract-detail panel">
          <div class="detail-top"><div class="document-symbol"><FileText :size="24"/></div><div><span class="detail-kicker">合同详情 / {{ selectedContract.id }}</span><h2>{{ selectedContract.asset }}</h2></div><span class="badge neutral">{{ selectedContract.status }}</span></div>
          <div class="contract-facts"><div><span>所属区域</span><strong>{{ selectedContract.area }}</strong></div><div><span>承租主体（虚构）</span><strong>{{ selectedContract.tenant }}</strong></div><div><span>租赁期间</span><strong>{{ selectedContract.start }} — {{ selectedContract.end }}</strong></div></div>
          <div class="account-summary"><div><span>{{ isExpense ? '本期合同应付' : '本期合同应收' }}</span><strong><small>¥</small>{{ money(selectedContract.receivable) }}</strong><em>以合同付款节点为依据</em></div><div><span>{{ isExpense ? '已关联支付' : '已关联到账' }}</span><strong class="received"><small>¥</small>{{ money(selectedContract.received) }}</strong><em>{{ payments.length }} 笔样例{{ isExpense ? '付款' : '收款' }}记录</em></div><div class="difference"><span>待核对差额<CircleAlert :size="14"/></span><strong><small>¥</small>{{ money(difference) }}</strong><em>可能存在未录入收款</em></div></div>
          <div class="ledger-heading"><h3>合同与到账轨迹</h3><span>依据可追溯</span></div>
          <div class="money-track"><span :style="{ width: `${Math.min(100, selectedContract.received / selectedContract.receivable * 100)}%` }"></span></div>
          <div class="receipt-timeline"><div class="timeline-item"><span class="timeline-node blue"><FileCheck2 :size="15"/></span><div><strong>合同约定付款节点</strong><p>{{ selectedContract.paymentNode || `年度应收 ¥${money(selectedContract.receivable)}` }}</p><small>来源：{{ selectedContract.clause?.split('：')[0] || '合同付款条款' }} · 演示条款</small></div><time>合同约定</time></div><div v-for="payment in payments" :key="payment.id" class="timeline-item"><span class="timeline-node teal"><ArrowDownLeft :size="16"/></span><div><strong>已匹配{{ isExpense ? '付款' : '收款' }} ¥{{ money(payment.amount) }}</strong><p>{{ payment.voucher }}</p><small>流水编号 {{ payment.id }}</small></div><time>{{ payment.date }}</time></div><div class="timeline-item unresolved" v-if="difference"><span class="timeline-node amber-bg"><CircleAlert :size="15"/></span><div><strong>差额 ¥{{ money(difference) }}，待人工核对</strong><p>请核实线下收款、未关联流水或补充凭证。</p></div></div></div>
          <div class="contract-document"><div class="paper-icon"><FileText :size="20"/></div><div><strong>{{ selectedContract.asset }}合同.pdf</strong><span>演示占位凭证 · 合同要素可供核对</span></div><button class="btn btn-quiet" @click="openFinding(contractFindings[0]?.id || ruralFindings[0]?.id || '')">查看依据<ArrowUpRight :size="14"/></button></div>
        </section>

        <aside class="ai-sidebar panel">
          <div class="ai-title"><span class="ai-icon"><ScanLine :size="21"/></span><div><h3>AI 辅助核验</h3><span>多源记录交叉比对</span></div><span class="tiny-ai">AI</span></div>
          <p class="ai-intro">关联合同条款与收款记录，提示值得进一步核对的业务疑点。</p>
          <button class="btn btn-primary verify-button" :disabled="verifying" @click="verify"><LoaderCircle v-if="verifying" class="spin" :size="16"/><ScanLine v-else :size="16"/>{{ verifying ? '正在模拟核验…' : verified ? '重新智能核验' : '开始智能核验' }}</button>
          <div v-if="verifying || verified" class="verification-steps"><div v-for="(step, index) in steps" :key="step" :class="{ done: verifyStep > index, current: verifyStep === index }"><span><Check v-if="verifyStep > index" :size="12"/><LoaderCircle v-else-if="verifyStep === index" :size="12" class="spin"/><b v-else>{{ index + 1 }}</b></span>{{ step }}</div></div>
          <div class="findings-heading"><span>{{ verified ? '本次辅助发现' : '待核查疑点' }}</span><b>{{ contractFindings.length }}</b></div>
          <button v-for="finding in contractFindings" :key="finding.id" class="finding-card" @click="openFinding(finding.id)"><span class="finding-label"><span class="status-dot amber"></span>{{ finding.status === '已完成' ? '人工核查已完成' : finding.status === '处理中' ? '已发起人工核查' : '需人工核查' }}<ChevronRight :size="15"/></span><h4>{{ finding.title }}</h4><p>{{ finding.evidence[0]?.question || '请结合原始凭证进一步核实。' }}</p><span class="evidence-link">查看数据来源与规则<ArrowUpRight :size="13"/></span></button>
          <div v-if="!contractFindings.length" class="clear-state"><ShieldCheck :size="28"/><strong>当前未发现关联疑点</strong><span>可点击智能核验重新比对样例记录</span></div>
          <div class="ai-boundary"><ShieldCheck :size="16"/><p>AI 仅提供辅助疑点，不构成违规认定。结论须由工作人员核查确认。</p></div>
        </aside>
      </div>
    </template>

    <div v-else-if="activeTab === '资产管理'" class="asset-overview">
      <div class="asset-feature panel"><div class="eyebrow">资产目录</div><h2>集体家底，看得清楚。</h2><p>从资产档案进入合同履约，逐项核对使用、租赁与收益情况。</p><div class="asset-total"><strong>{{ store.contracts.length.toString().padStart(2, '0') }}</strong><span>项演示资产<br/>全部已关联合同档案</span></div><span class="muted">资产分布为虚构样例，非实际清产核资结果。</span></div>
      <div class="asset-cards"><button v-for="(contract, index) in store.contracts" :key="contract.id" class="asset-card panel" @click="chooseContract(contract.id); activeTab = '合同台账'"><div class="asset-art"><Landmark v-if="index === 0" :size="50" stroke-width="1.2"/><FolderOpen v-else-if="index === 1" :size="50" stroke-width="1.2"/><Banknote v-else :size="50" stroke-width="1.2"/><span>资产档案 0{{ index + 1 }}</span></div><div class="asset-card-copy"><span>{{ contract.area }}</span><h3>{{ contract.asset }}</h3><div><p>{{ contract.id === 'SZ-HT-2026-025' ? '合同应付' : '年度应收' }}<strong>¥ {{ money(contract.receivable) }}</strong></p><ArrowUpRight :size="19"/></div><small>查看资产与关联合同</small></div></button></div>
    </div>

    <div v-else-if="activeTab === '收支核对'" class="reconcile-view panel">
      <div class="reconcile-header"><div><div class="eyebrow">合同与流水核对</div><h2>逐笔对照，有据可循</h2><p class="muted">补充收款记录后，合同账面差额实时更新；原始凭证仍须人工核实。</p></div><select class="field" v-model="selectedId"><option v-for="contract in store.contracts" :value="contract.id" :key="contract.id">{{ contract.asset }}</option></select></div>
      <div class="reconcile-balance"><div><FileText :size="24"/><span>{{ isExpense ? '合同应付' : '合同应收' }}<strong>¥ {{ money(selectedContract?.receivable || 0) }}</strong></span></div><b>−</b><div><ReceiptText :size="24"/><span>{{ isExpense ? '关联支付' : '关联到账' }}<strong>¥ {{ money(selectedContract?.received || 0) }}</strong></span></div><b>=</b><div class="balance-result"><CircleAlert :size="24"/><span>待核对差额<strong>¥ {{ money(difference) }}</strong></span></div></div>
      <div class="ledger-heading"><h3>{{ isExpense ? '付款流水明细' : '收款流水明细' }}</h3><button class="btn btn-quiet" :disabled="addedReceipt || !difference" @click="addReceipt"><ArrowDownLeft :size="15"/>{{ addedReceipt ? '已补充演示凭证' : '补充演示收款记录' }}</button></div>
      <div v-if="actionMessage" class="inline-feedback"><Check :size="16"/>{{ actionMessage }}</div>
      <div class="receipt-table"><div class="receipt-row table-head"><span>到账日期 / 流水编号</span><span>凭证摘要</span><span>到账金额</span><span>关联情况</span></div><div v-for="payment in payments" :key="payment.id" class="receipt-row"><span><strong>{{ payment.date }}</strong><small>{{ payment.id }}</small></span><span>{{ payment.voucher }}</span><strong>¥ {{ money(payment.amount) }}</strong><span class="badge" :class="payment.id.startsWith('PAY-MANUAL') ? 'orange' : 'green'">{{ payment.id.startsWith('PAY-MANUAL') ? '待人工核实' : '已关联合同' }}</span></div></div>
      <div class="reconcile-note"><CircleAlert :size="17"/><p><strong>差额说明</strong>账面未匹配不等于实际欠缴。请核对线下收款、票据录入和跨期支付情况后，再形成核查结论。</p></div>
    </div>

    <div v-else class="risk-view"><div class="risk-intro"><div class="eyebrow">疑点来源与核查依据</div><h2>每一条疑点，都有依据。</h2><p class="muted">从规则命中到证据对照，再由工作人员决定是否发起核查。</p><span class="ai-note">AI 辅助结果 · 需人工复核</span></div><div class="risk-cards"><button v-for="finding in ruralFindings" :key="finding.id" class="risk-card panel" @click="openFinding(finding.id)"><div class="risk-card-top"><span class="risk-mark"><CircleAlert :size="22"/></span><span class="badge" :class="finding.status === '已完成' ? 'green' : finding.status === '处理中' ? 'blue' : 'orange'">{{ finding.status }}</span></div><span class="risk-id">{{ finding.id }} · {{ finding.area }}</span><h3>{{ finding.title }}</h3><p>{{ finding.evidence[0]?.question }}</p><div class="risk-rule"><span>命中规则</span>{{ finding.evidence[0]?.rule }}</div><div class="risk-card-foot"><span>{{ finding.evidence.length }} 组来源证据</span><span>查看证据<ArrowUpRight :size="15"/></span></div></button></div></div>

    <Teleport to="body"><div v-if="drawerFinding" class="asset-drawer-backdrop" @click.self="drawerId = null"><aside class="asset-evidence-drawer"><header><div><div class="eyebrow">原始记录与规则对照</div><h2>疑点证据对照</h2></div><button class="icon-close" aria-label="关闭证据" @click="drawerId = null"><X :size="20"/></button></header><div class="drawer-content"><span class="badge" :class="drawerFinding.status === '已完成' ? 'green' : drawerFinding.status === '处理中' ? 'blue' : 'orange'">{{ drawerFinding.status }}</span><h3>{{ drawerFinding.title }}</h3><p class="drawer-subtitle">{{ drawerFinding.area }} · {{ drawerFinding.sourceId }}</p><div v-if="drawerContract" class="source-comparison"><div><FileText :size="15"/><strong>合同原始条款</strong><span>{{ drawerContract.id }}</span></div><blockquote>{{ drawerContract.clause }}</blockquote><div class="source-payment-title"><ReceiptText :size="15"/><strong>关联收付款记录</strong></div><div v-for="payment in drawerPayments" :key="payment.id" class="source-payment"><span>{{ payment.date }}<small>{{ payment.id }}</small></span><strong>¥ {{ money(payment.amount) }}</strong><p>{{ payment.voucher }}</p></div><div class="source-balance"><span>合同{{ drawerContract.id === 'SZ-HT-2026-025' ? '应付' : '应收' }} ¥{{ money(drawerContract.receivable) }}</span><span>关联{{ drawerContract.id === 'SZ-HT-2026-025' ? '支付' : '到账' }} ¥{{ money(drawerContract.received) }}</span><strong>待核差额 ¥{{ money(Math.max(0, drawerContract.receivable - drawerContract.received)) }}</strong></div></div><div class="evidence-group" v-for="(evidence, index) in drawerFinding.evidence" :key="index"><div class="evidence-number">{{ (index + 1).toString().padStart(2, '0') }}<span>{{ evidence.source }}</span></div><blockquote>{{ evidence.excerpt }}</blockquote><div class="evidence-detail"><span>命中规则</span><p>{{ evidence.rule }}</p></div><div class="evidence-detail question"><span>待核问题</span><p>{{ evidence.question }}</p></div></div><div class="ai-boundary"><ShieldCheck :size="17"/><p>演示研判仅提示数据记录与业务规则的差异。未核实前，不得据此认定欠缴或违规。</p></div><div v-if="taskForFinding || actionMessage" class="task-created"><ClipboardCheck :size="22"/><div><strong>{{ taskForFinding?.status === '已完成' ? '人工核查已完成' : '已进入人工核查流程' }}</strong><p>{{ taskForFinding?.assignee || assignee }} · 截止 {{ taskForFinding?.deadline || deadline }}</p><span>任务状态与监督总览实时联动</span></div></div><form v-else-if="assignmentOpen" class="assignment-form" @submit.prevent="createTask"><h4>确认核查责任与办理时限</h4><label>责任组<select class="field" v-model="assignee"><option>第二监督检查室</option><option>农村三资专项核查组</option><option>派驻监督工作组</option></select></label><label>办理期限<input class="field" type="date" v-model="deadline" required/></label><button class="btn btn-primary" type="submit"><Check :size="16"/>人工确认并创建任务</button></form></div><footer><span>AI 辅助结果 · 需人工复核</span><button v-if="!taskForFinding && !assignmentOpen" class="btn btn-primary" @click="assignmentOpen = true"><ClipboardCheck :size="16"/>发起人工核查</button><button v-else class="btn btn-quiet" @click="drawerId = null">返回监督台账</button></footer></aside></div></Teleport>
  </div>
</template>

<style scoped>
.assets-page{padding-bottom:12px;color:var(--ink)}
